function UIMazeBagDialog:Awake()
    self.EventMazeUseItem = Events.AddListener(Constants.EventNames.MazeUseItem, Bind(self, self.OnMazeUseItem))
    self:FillSelfCf()
    self:FillSelf()
end

function UIMazeBagDialog:FillSelfCf()
    SetButtonAction(self.btnUse, Bind(self, self.OnbtnUse))
    SetButtonAction(self.closeBtn, Bind(self, self.OncloseBtn))
    SetButtonAction(self.bg, function()
        if self.isShowUseItem then
            KTool.SetActive(self.useItem.gameObject, false)
            self.isShowUseItem = not self.isShowUseItem
        elseif self.isShowDesc then
            KTool.SetActive(self.desc.gameObject, false)
            self.isShowDesc = not self.isShowDesc
            self:RefeshChoose()
        else
            self:OncloseBtn()
        end 
    end)
end

function UIMazeBagDialog:FillSelf()
    CfUtils.FillCfText(self.cfText4, localize("使用了道具"))
    CfUtils.FillCfText(self.content, localize("迷宫背包仅存放本次背包。。。。。。"))
    CfUtils.FillCfText(self.title, localize("背包"))
    CfUtils.FillCfText(self.cfText10, localize("暂未获得任何道具"))
    KTool.SetActive(self.cont, true)

    self.datas = self:GetLoopData()
    self.itemView1:InitListView(#self.datas, Bind(self, self.OnGetItemByIndex))

    --背包里一个东西都没有
    KTool.SetActive(self.noItemBg.gameObject, #self.datas <= 0)
    KTool.SetActive(self.itemView1.gameObject, #self.datas > 0)
end

function UIMazeBagDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local cell
    local luaPath
    local data = self.datas[index + 1]
    if checkNumber(data._tarType) == 1 then     --物品
        cell = listView:NewListViewItem("items")
        luaPath = UIMazeBagItemsNode
    elseif checkNumber(data._tarType) == 2 then   --标题
        cell = listView:NewListViewItem("titleItem")
        luaPath = UIMazeBagTitleNode
    end
    local scr = CfUtils.GetLuaScr(cell, luaPath)
    if scr then
        scr:Refresh(data, function(itemGo, id)
            self:FillDesc(itemGo, id, Constants.IDType.MazeItem)
            self:RefeshChoose(itemGo)
        end)
    end
    return cell
end

--刷新选中状态
function UIMazeBagDialog:RefeshChoose(go)
    local chooseGo
    --先关闭上次选中的
    if self.curSelectGo then
        local scr = CfUtils.GetLuaScr(self.curSelectGo, UIMazeBagItemNode)
        if scr then
            scr:RefreshChoose(false)
        end
    end

    --打开现在选中的
    self.curSelectGo = go
    if self.curSelectGo then
        local scr = CfUtils.GetLuaScr(self.curSelectGo, UIMazeBagItemNode)
        if scr then
            scr:RefreshChoose(true)
        end
    end
end

function UIMazeBagDialog:GetLoopData()
    local mazeBagComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MazeBagComponent, Constants.MazeBagEntityId)

    local itemData = mazeBagComp:GetItemArr()
    local buffData = mazeBagComp:GetRelicsArr()
    local debuffData = mazeBagComp:GetCursesArr()

    local data = {
        [1] = {
            ["name"] = localize("补给"),
            ["num"] = #itemData,
            ["img"] = mazeBagComp:GetTitleIma(Constants.IDType.MazeItem),
            ["_tarType"] = 2,
        },
        [2] = {
            ["name"] = localize("谣言效应"),
            ["num"] = #debuffData,
            ["img"] = mazeBagComp:GetTitleIma(Constants.IDType.Curses),
            ["_tarType"] = 2,
        },
        [3] = {
            ["name"] = localize("情报效应"),
            ["num"] = #buffData,
            ["img"] = mazeBagComp:GetTitleIma(Constants.IDType.Relics),
            ["_tarType"] = 2,
        }
    }

    local allData = {}
    if data[1].num > 0 then
        table.insert(allData, data[1])
        local t = CfUtils.GetGroupArrays(itemData, 4)
        if t and #t > 0 then
            for i = 1, #t do
                table.insert(allData, t[i])
            end
        end
    end

    if data[2].num > 0 then
        table.insert(allData, data[2])
        t = CfUtils.GetGroupArrays(debuffData, 4)
        if t and #t > 0 then
            for i = 1, #t do
                table.insert(allData, t[i])
            end
        end
    end

    if data[3].num > 0 then
        table.insert(allData, data[3])
        t = CfUtils.GetGroupArrays(buffData, 4)
        if t and #t > 0 then
            for i = 1, #t do
                table.insert(allData, t[i])
            end
        end
    end

    return allData
end

--[[
    @desc:  物品点击
    author:{author}
    time:2020-04-24 17:18:06
    --@itemId:id
	--@type: 物品类型
    @return:
]]
function UIMazeBagDialog:FillDesc(go, itemId, itemType)
    if self.curSelectItemId and checkNumber(self.curSelectItemId) == itemId then 
        return
    end
    local mazeBagComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MazeBagComponent, Constants.MazeBagEntityId)

    self.curSelectItemId = itemId
    local itemType = checkNumber(GoodsUtils.GetIdType(itemId, Constants.IDArea.Maze))

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(itemId, Constants.IDArea.Maze)
    CfUtils.FillImage(self.desc, mazeBagComp:GetItemShowBg(itemType), true)

    self:RefreshItemNode(self.itemPar, itemId, nil, 1, Constants.IDArea.Maze)
    if goodsVo then
        CfUtils.FillText(self.name, goodsVo.name)
        if itemType == Constants.IDType.Curses then
            self.name.color = Color.New(255/255, 0/255, 0/255, 255/255)
            self.descSec.color = Color.New(255/255, 255/255, 255/255, 255/255)
        elseif itemType == Constants.IDType.Relics then
            self.name.color = Color.New(255/255, 255/255, 255/255, 255/255)
            self.descSec.color = Color.New(255/255, 166/255, 57/255, 255/255)
        elseif itemType == Constants.IDType.MazeItem then
            self.name.color = Color.New(71/255, 71/255, 71/255, 255/255)
            self.descSec.color = Color.New(126/255, 126/255, 126/255, 255/255)
        end
        CfUtils.FillText(self.descSec, goodsVo.description)
    end
    
    KTool.SetActive(self.itemBg, itemType == Constants.IDType.MazeItem)
    KTool.SetActive(self.buffBg, itemType == Constants.IDType.Relics)
    KTool.SetActive(self.debuffBg, itemType == Constants.IDType.Curses)

    KTool.SetActive(self.btnUse, itemType == Constants.IDType.MazeItem)

    KTool.SetActive(self.useItem, false)
    self.isShowUseItem = false
    KTool.SetActive(self.desc, true)
    self.isShowDesc = true
end

--使用完道具的效果   id 和 服务器的使用目标数据
function UIMazeBagDialog:FillUseEffectShow(itemId, jsonData)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(itemId, Constants.IDArea.Maze)

    for i = 1, 2 do 
        local go = self.users.transform:Find("go"..i)
        if not go then 
            go = CfUtils.InstantiateGo(self.userGo, self.users)
            go.name = "go"..i
        end

        local scr = CfUtils.GetLuaScr(go, UIMazeBagUseResultNode)
        if scr then
            scr:Refresh(itemId, jsonData, i)
        end
    end
    KTool.SetActive(self.useItem, true)
    self.isShowUseItem = true
end

function UIMazeBagDialog:RefreshItemNode(goPar, itemId, num, scale, idAreaType, cb, id)
    if not goPar then
        return
    end

    if not self._itemLoader then
        self._itemLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/GoodNode.prefab", nil, true)
    end
    if self._itemLoader.IsSuccess then
        local go = goPar.transform:Find("item")
        if not go then 
            go = CfUtils.InstantiateGo(self._itemLoader.ResultObject, goPar)
            go.name = "item"
        end
        if go then
            CfUtils.RefeshGoodGo(go, itemId, num, scale, idAreaType, cb, id)
        end
    end
end

function UIMazeBagDialog:OnbtnUse()
    local itemType = GoodsUtils.GetIdType(self.curSelectItemId, Constants.IDArea.Maze)
    if itemType == Constants.IDType.MazeItem then
        local item = GoodsConfMgr:GetInstance():GetGoodsVoById(self.curSelectItemId, Constants.IDArea.Maze)
        if not item then
            return
        end
        local targetType = checkNumber(item.targetType)
        if targetType == Constants.MazeItemTargetType.Appoint then
            UIModule.OpenDialog({id = Constants.UITypeIds.UIMazeTeamDialog, parameters = {useItemId = self.curSelectItemId}})
        else
            local MazeMgr = import('Game.Maze.MazeMgr')
            MazeMgr:GetInstance():MazeUseGoods(self.curSelectItemId, targetType, 0)
        end
    end
end

function UIMazeBagDialog:OncloseBtn()
    KTool.SetActive(self.useItem, false)
    KTool.SetActive(self.desc, false)

    UIModule.CloseDialog(self.controller)
end

--使用了物品
function UIMazeBagDialog:OnMazeUseItem(data) 
    KTool.SetActive(self.desc, false)
    self.isShowDesc = false
    if not data or not data.itemId then return end
    self:FillUseEffectShow(data.itemId, data.jsonData)

    self.datas = self:GetLoopData()
    GameUtils.ReloadData(self.itemView1, #self.datas)
end

